// Jonker-Volgenant shortest-augmenting-path assignment solver (dense).
// Returns row->col assignment (0-based) for an n x n C-order double matrix.
#include <cstdint>
#include <vector>
#include <limits>
#include <cstring>
#include <algorithm>

static inline int find_match_col(const std::vector<int>& row_of, int i, int n) {
    for (int j = 1; j <= n; ++j) if (row_of[j] == i) return j;
    return 0;
}

extern "C" void lapjv(const double* C, int n, int* row_to_col) {
    const double INF = std::numeric_limits<double>::infinity();
    std::vector<double> v(n + 1, 0.0), u(n + 1, 0.0), d(n + 1);
    std::vector<int> row_of(n + 1, 0), pred(n + 1, 0), match_col(n + 1, 0);
    std::vector<char> seen(n + 1);

    auto cost = [&](int i, int j) -> double {
        return C[(size_t)(i - 1) * n + (j - 1)];
    };

    for (int i = 1; i <= n; ++i) {
        std::fill(d.begin(), d.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        for (int j = 1; j <= n; ++j) {
            d[j] = cost(i, j) - v[j];
            pred[j] = i;
        }
        int jmin = 0;
        int i_cur = i;
        while (true) {
            double mn = INF;
            jmin = 0;
            for (int j = 1; j <= n; ++j) if (!seen[j] && d[j] < mn) { mn = d[j]; jmin = j; }
            seen[jmin] = 1;
            int i_match = row_of[jmin];
            if (i_match == 0) {
                // update dual variables for scanned columns
                for (int j = 1; j <= n; ++j) if (seen[j]) v[j] += d[j] - mn;
                u[i] = u[i]; // unused
                // augment along alternating path
                int j = jmin;
                while (j) {
                    int i_pred = pred[j];
                    int j_prev = match_col[i_pred];
                    row_of[j] = i_pred;
                    match_col[i_pred] = j;
                    j = j_prev;
                }
                break;
            }
            // relax edges from the row matched to jmin
            double base = mn;
            double vjmin = v[jmin];
            double c_match = cost(i_match, jmin);
            for (int j = 1; j <= n; ++j) if (!seen[j]) {
                double nd = base + cost(i_match, j) - v[j] - (c_match - vjmin);
                if (nd < d[j]) { d[j] = nd; pred[j] = i_match; }
            }
        }
    }
    for (int i = 1; i <= n; ++i) row_to_col[i - 1] = match_col[i] - 1;
}
