// Dense Jonker-Volgenant linear assignment solver.
// Port of the classic lapjv (Jonker & Volgenant 1987) structure.
#include <cstdint>
#include <vector>
#include <cmath>
#include <limits>
#include <algorithm>
#include <cstring>

extern "C" void lapjv(const double* cost, int n, int* rowsol_out) {
    const double INF = std::numeric_limits<double>::max() / 4;
    const int N = n;

    std::vector<double> u(N, 0.0), v(N, 0.0);
    std::vector<int> rowsol(N, -1), colsol(N, -1);
    std::vector<double> d(N);
    std::vector<int> pred(N), collist(N);
    std::vector<char> free_col(N, 1);

    // ---- COLUMN REDUCTION ----
    // For each column, find the row with minimum cost; assign greedily in reverse.
    std::vector<int> min_row(N);
    for (int j = 0; j < N; ++j) {
        double mn = INF; int r = 0;
        const double* colbase = cost; // row-major: cost[i*N + j]
        for (int i = 0; i < N; ++i) {
            double c = cost[(size_t)i * N + j];
            if (c < mn) { mn = c; r = i; }
        }
        v[j] = mn;
        min_row[j] = r;
    }
    // reverse scan assignment
    std::vector<char> row_taken(N, 0);
    for (int j = N - 1; j >= 0; --j) {
        int i = min_row[j];
        if (!row_taken[i]) {
            rowsol[i] = j; colsol[j] = i; row_taken[i] = 1; free_col[j] = 0;
        }
    }
    // reduction transfer: for unassigned rows, reduce
    for (int i = 0; i < N; ++i) if (rowsol[i] < 0) {
        double mn = INF;
        for (int j = 0; j < N; ++j) {
            double red = cost[(size_t)i * N + j] - v[j];
            if (red < mn) mn = red;
        }
        u[i] = mn;
    }

    // ---- AUGMENTING ROW REDUCTION ----
    // two passes
    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < N; ++i) if (rowsol[i] < 0) {
            // find minimum and second minimum reduced cost
            double mn1 = INF, mn2 = INF; int j1 = -1;
            for (int j = 0; j < N; ++j) {
                double red = cost[(size_t)i * N + j] - v[j];
                if (red < mn1) { mn2 = mn1; mn1 = red; j1 = j; }
                else if (red < mn2) { mn2 = red; }
            }
            u[i] = mn1;
            v[j1] -= (mn2 - mn1); // transfer
            // if column j1 is free or we can reassign
            int i_old = colsol[j1];
            if (i_old >= 0) { rowsol[i_old] = -1; }
            rowsol[i] = j1; colsol[j1] = i;
        }
    }

    // collect free rows
    std::vector<int> freerows;
    freerows.reserve(N);
    for (int i = 0; i < N; ++i) if (rowsol[i] < 0) freerows.push_back(i);

    // ---- AUGMENTATION (shortest paths) ----
    std::vector<char> seen(N);
    for (int f = 0; f < (int)freerows.size(); ++f) {
        int i0 = freerows[f];
        if (rowsol[i0] >= 0) continue; // assigned during earlier augmentation? no, free rows stay free until augmented
        std::fill(d.begin(), d.end(), INF);
        std::fill(seen.begin(), seen.end(), 0);
        int endcol = -1;
        // initialize distances from i0
        for (int j = 0; j < N; ++j) {
            d[j] = cost[(size_t)i0 * N + j] - v[j] - u[i0];
            pred[j] = i0;
        }
        int lastfree = -1;
        while (endcol < 0) {
            // find minimum unscanned column
            double mn = INF; int jmin = -1;
            for (int j = 0; j < N; ++j) if (!seen[j] && d[j] < mn) { mn = d[j]; jmin = j; }
            seen[jmin] = 1;
            int i_match = colsol[jmin];
            if (i_match < 0) { endcol = jmin; 
                // dual update
                for (int j = 0; j < N; ++j) if (seen[j]) v[j] += d[j] - mn;
                u[i0] += mn; // ? handled via path
                break;
            }
            // relax
            double base = mn;
            double cmatch = cost[(size_t)i_match * N + jmin];
            double vj = v[jmin];
            const double* rowp = cost + (size_t)i_match * N;
            for (int j = 0; j < N; ++j) if (!seen[j]) {
                double nd = base + rowp[j] - v[j] - (cmatch - vj);
                if (nd < d[j]) { d[j] = nd; pred[j] = i_match; }
            }
        }
        // augment
        int j = endcol;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jprev = rowsol[i];
            rowsol[i] = j;
            if (i == i0) break;
            j = jprev;
        }
    }

    for (int i = 0; i < N; ++i) rowsol_out[i] = rowsol[i];
}
