// Shortest-augmenting-path assignment with a binary heap (Dijkstra).
// Dual-feasible reduced costs; warm-started by a greedy column reduction.
#include <cstdint>
#include <vector>
#include <limits>
#include <algorithm>
#include <cstring>

struct Heap {
    std::vector<int> h;       // heap of column indices
    std::vector<int> pos;     // position in heap or -1
    std::vector<double> key;
    int n;
    explicit Heap(int n): h(n), pos(n, -1), key(n), n(0) {}
    void clear() { for (int i = 0; i < n; ++i) pos[h[i]] = -1; n = 0; }
    void push(int j, double k) {
        key[j] = k;
        int i = n++;
        h[i] = j; pos[j] = i;
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (key[h[p]] <= key[h[i]]) break;
            std::swap(h[p], h[i]); pos[h[p]] = p; pos[h[i]] = i; i = p;
        }
    }
    void decrease(int j, double k) {
        if (pos[j] < 0) { push(j, k); return; }
        if (k >= key[j]) return;
        key[j] = k;
        int i = pos[j];
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (key[h[p]] <= key[h[i]]) break;
            std::swap(h[p], h[i]); pos[h[p]] = p; pos[h[i]] = i; i = p;
        }
    }
    int pop() {
        int r = h[0];
        pos[r] = -1;
        n--;
        if (n > 0) {
            h[0] = h[n]; pos[h[0]] = 0;
            int i = 0;
            while (true) {
                int l = i*2+1, rr = l+1, b = i;
                if (l < n && key[h[l]] < key[h[b]]) b = l;
                if (rr < n && key[h[rr]] < key[h[b]]) b = rr;
                if (b == i) break;
                std::swap(h[i], h[b]); pos[h[i]] = i; pos[h[b]] = b; i = b;
            }
        }
        return r;
    }
    bool empty() const { return n == 0; }
};

extern "C" void lapjv(const double* cost, int n, int* rowsol_out) {
    const double INF = std::numeric_limits<double>::infinity();
    const int N = n;

    std::vector<double> u(N, 0.0), v(N, 0.0);
    std::vector<int> rowsol(N, -1), colsol(N, -1);

    // Greedy column reduction for a warm start (reverse order)
    std::vector<int> min_row(N);
    for (int j = 0; j < N; ++j) {
        double mn = INF; int r = 0;
        for (int i = 0; i < N; ++i) {
            double c = cost[(size_t)i * N + j];
            if (c < mn) { mn = c; r = i; }
        }
        v[j] = mn; min_row[j] = r;
    }
    for (int j = N - 1; j >= 0; --j) {
        int i = min_row[j];
        if (rowsol[i] < 0) { rowsol[i] = j; colsol[j] = i; }
    }
    // set row duals for matched rows so reduced cost of match is 0
    for (int i = 0; i < N; ++i) if (rowsol[i] >= 0) {
        u[i] = cost[(size_t)i * N + rowsol[i]] - v[rowsol[i]];
    }

    std::vector<double> dist(N);
    std::vector<int> pred(N);
    std::vector<char> scanned(N);
    Heap heap(N);

    for (int i0 = 0; i0 < N; ++i0) {
        if (rowsol[i0] >= 0) continue;

        std::fill(dist.begin(), dist.end(), INF);
        std::fill(scanned.begin(), scanned.end(), 0);
        heap.clear();

        const double* row0 = cost + (size_t)i0 * N;
        for (int j = 0; j < N; ++j) {
            double dj = row0[j] - v[j];
            dist[j] = dj;
            pred[j] = i0;
            heap.push(j, dj);
        }

        int endcol = -1;
        while (!heap.empty()) {
            int j = heap.pop();
            if (scanned[j]) continue;
            scanned[j] = 1;
            double dj = dist[j];
            int i_match = colsol[j];
            if (i_match < 0) { endcol = j; break; }
            // relax from matched row
            const double* rowp = cost + (size_t)i_match * N;
            double base = dj - (rowp[rowsol[i_match]] - v[j]); // rowsol[i_match]==j
            // since matched edge reduced cost is 0: cost[i_match,j] - u[i_match] - v[j] == 0
            // nd = dj + cost[i_match, j2] - u[i_match] - v[j2]
            //    = dj + cost[i_match, j2] - v[j2] - (cost[i_match, j] - v[j])
            double cmatch_v = rowp[j] - v[j];
            for (int j2 = 0; j2 < N; ++j2) {
                if (scanned[j2]) continue;
                double nd = dj + rowp[j2] - v[j2] - cmatch_v;
                if (nd < dist[j2]) {
                    dist[j2] = nd;
                    pred[j2] = i_match;
                    heap.decrease(j2, nd);
                }
            }
        }

        // dual update: v[j] += dist[j] - dist[endcol] for scanned columns
        double delta = dist[endcol];
        for (int j = 0; j < N; ++j) if (scanned[j]) v[j] += dist[j] - delta;
        u[i0] = delta;

        // update u for rows whose match was scanned (except i0)
        for (int j = 0; j < N; ++j) if (scanned[j] && colsol[j] >= 0) {
            int i = colsol[j];
            u[i] = cost[(size_t)i * N + j] - v[j];
        }

        // augment
        int j = endcol;
        while (true) {
            int i = pred[j];
            colsol[j] = i;
            int jprev = rowsol[i];
            rowsol[i] = j;
            if (i == i0) break;
            j = jprev;
        }
    }

    for (int i = 0; i < N; ++i) rowsol_out[i] = rowsol[i];
}
