// Epsilon-scaling auction algorithm for the dense assignment problem.
// Bertsekas auction with Gauss-Seidel bidding and epsilon scaling.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>
#include <limits>

extern "C" int auction(const double* cost, int n, int* rowsol, double eps_factor, int phases) {
    const int N = n;
    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), assign(N, -1);

    // cost scale
    double cmax = 0.0;
    for (size_t i = 0, nn = (size_t)N*N; i < nn; i += 97) cmax = std::max(cmax, cost[i]);
    double eps = cmax / 4.0;
    double eps_min = cmax / ((double)N * N) * 0.5;

    for (int phase = 0; phase < phases && eps > eps_min * 0.25; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        int nunassigned = N;
        std::vector<int> un(N);
        for (int i = 0; i < N; ++i) un[i] = i;
        int guard = 0;
        int guardmax = N * 40;
        while (nunassigned > 0) {
            if (++guard > guardmax) break;
            int newn = 0;
            std::vector<int> next(nunassigned);
            for (int u = 0; u < nunassigned; ++u) {
                int i = un[u];
                const double* row = cost + (size_t)i * N;
                double best = std::numeric_limits<double>::infinity();
                double second = std::numeric_limits<double>::infinity();
                int bj = 0;
                for (int j = 0; j < N; ++j) {
                    double val = row[j] + price[j];
                    if (val < best) { second = best; best = val; bj = j; }
                    else if (val < second) { second = val; }
                }
                double bid = price[bj] + (second - best) + eps;
                int prev = owner[bj];
                if (prev != -1) { assign[prev] = -1; next[newn++] = prev; }
                else { nunassigned--; }
                owner[bj] = i;
                assign[i] = bj;
                price[bj] = bid;
            }
            // rebuild unassigned list: those in next plus any still unassigned not displaced
            // The loop above only iterates current unassigned; displaced go to next.
            // But nunassigned accounting: we decrement when taking a free column, and
            // displaced persons are added to next. Count must match next size.
            un.swap(next);
            nunassigned = newn;
        }
        eps *= eps_factor;
    }
    int ok = 1;
    for (int i = 0; i < N; ++i) { rowsol[i] = assign[i]; if (assign[i] < 0) ok = 0; }
    return ok;
}
