// Jacobi (parallel-style) epsilon-scaling auction for dense assignment.
// Each round every unassigned person bids; the highest bidder for each object wins.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>
#include <cstring>

extern "C" int auction(const double* cost, int n, int* rowsol, double eps_factor, int phases) {
    const int N = n;
    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), assign(N, -1);
    std::vector<int> bid_person(N, -1);
    std::vector<double> bid_amount(N, 0.0);
    std::vector<char> is_unassigned(N, 1);

    double cmax = 0.0;
    for (size_t i = 0, nn = (size_t)N * N; i < nn; i += 64) cmax = std::max(cmax, cost[i]);
    double eps = cmax / 2.0;
    double eps_min = cmax / ((double)N * N);

    for (int phase = 0; phase < phases && eps >= eps_min * 0.5; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        std::fill(is_unassigned.begin(), is_unassigned.end(), 1);
        int nunassigned = N;
        int guard = 0;
        const int guardmax = N * 100;
        while (nunassigned > 0 && guard++ < guardmax) {
            std::fill(bid_person.begin(), bid_person.end(), -1);
            for (int i = 0; i < N; ++i) {
                if (!is_unassigned[i]) continue;
                const double* row = cost + (size_t)i * N;
                double best = std::numeric_limits<double>::infinity();
                double second = std::numeric_limits<double>::infinity();
                int bj = 0;
                for (int j = 0; j < N; ++j) {
                    double val = row[j] + price[j];
                    if (val < best) { second = best; best = val; bj = j; }
                    else if (val < second) second = val;
                }
                double bid = price[bj] + (second - best) + eps;
                if (bid_person[bj] < 0 || bid > bid_amount[bj]) {
                    bid_person[bj] = i;
                    bid_amount[bj] = bid;
                }
            }
            // assign winners; losers stay unassigned
            std::fill(is_unassigned.begin(), is_unassigned.end(), 1);
            nunassigned = N;
            for (int j = 0; j < N; ++j) {
                int i = bid_person[j];
                if (i < 0) { owner[j] = -1; continue; }
                owner[j] = i;
                assign[i] = j;
                price[j] = bid_amount[j];
                is_unassigned[i] = 0;
                nunassigned--;
            }
        }
        if (eps <= eps_min) break;
        eps *= eps_factor;
        if (eps < eps_min) eps = eps_min;
    }
    int ok = 1;
    for (int i = 0; i < N; ++i) { rowsol[i] = assign[i]; if (assign[i] < 0) ok = 0; }
    // verify permutation
    std::vector<char> seen(N, 0);
    for (int i = 0; i < N; ++i) {
        int j = assign[i];
        if (j < 0 || j >= N || seen[j]) { ok = 0; break; }
        seen[j] = 1;
    }
    return ok;
}
