// Gauss-Seidel epsilon-scaling auction, optimized.
// Bids are processed one person at a time so prices update immediately.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>
#include <cstring>

extern "C" int auction(const double* cost, int n, int* rowsol) {
    const int N = n;
    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), assign(N, -1);

    double cmax = 0.0, cmin = std::numeric_limits<double>::infinity();
    for (size_t i = 0, nn = (size_t)N * N; i < nn; i += 48) {
        cmax = std::max(cmax, cost[i]);
        cmin = std::min(cmin, cost[i]);
    }
    double range = cmax - cmin;
    double eps = range / 4.0;
    // epsilon must end below 1/N of the smallest cost gap; use a safe bound
    double eps_min = range / (N + 1.0) / (N + 1.0);

    std::vector<int> un(N), next(N);
    const int MAX_PHASES = 60;

    for (int phase = 0; phase < MAX_PHASES; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        for (int i = 0; i < N; ++i) un[i] = i;
        int nun = N;
        long guard = 0;
        long guardmax = (long)N * 300;
        bool done = false;
        while (nun > 0 && guard++ < guardmax) {
            int newn = 0;
            for (int u = 0; u < nun; ++u) {
                int i = un[u];
                const double* row = cost + (size_t)i * N;
                double best = std::numeric_limits<double>::infinity();
                double second = std::numeric_limits<double>::infinity();
                int bj = 0;
                for (int j = 0; j < N; ++j) {
                    double val = row[j] + price[j];
                    if (val < best) { second = best; best = val; bj = j; }
                    else if (val < second) { second = val; }
                }
                double bid = price[bj] + (second - best) + eps;
                int prev = owner[bj];
                if (prev != -1) { assign[prev] = -1; next[newn++] = prev; }
                owner[bj] = i;
                assign[i] = bj;
                price[bj] = bid;
            }
            un.swap(next);
            nun = newn;
            if (nun == 0) done = true;
        }
        if (!done) {
            // did not converge at this epsilon; shrink faster and retry with fresh prices
            std::fill(price.begin(), price.end(), 0.0);
        }
        if (eps <= eps_min && done) break;
        eps *= 0.2;
        if (eps < eps_min) eps = eps_min;
    }

    int ok = 1;
    std::vector<char> seen(N, 0);
    for (int i = 0; i < N; ++i) {
        int j = assign[i];
        rowsol[i] = j;
        if (j < 0 || j >= N || seen[j]) ok = 0;
        else seen[j] = 1;
    }
    return ok;
}
