// Exact dense assignment solver: column reduction + augmenting row reduction
// + successive shortest augmenting paths (Dijkstra). Returns row->col (0-based).
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>
#include <cstring>

static const double INF = 1e100;

extern "C" void solve_assignment(const double* cost, int n, int* row_of_out) {
    const int N = n;
    std::vector<double> u(N, 0.0), v(N, 0.0);
    std::vector<int> x(N, -1), y(N, -1); // x[row]=col, y[col]=row

    // ---------- column reduction ----------
    for (int j = N - 1; j >= 0; --j) {
        double mn = INF; int imin = 0;
        for (int i = 0; i < N; ++i) {
            double h = cost[(size_t)i * N + j];
            if (h < mn) { mn = h; imin = i; }
        }
        v[j] = mn;
        if (x[imin] < 0) { x[imin] = j; y[j] = imin; }
    }

    auto free_list = [&]() {
        std::vector<int> fr; fr.reserve(N);
        for (int i = 0; i < N; ++i) if (x[i] < 0) fr.push_back(i);
        return fr;
    };

    // ---------- augmenting row reduction ----------
    for (int pass = 0; pass < 2; ++pass) {
        std::vector<int> fr = free_list();
        for (int i : fr) {
            if (x[i] >= 0) continue;
            double min1 = INF, min2 = INF; int j1 = -1;
            const double* row = cost + (size_t)i * N;
            double ui = u[i];
            for (int j = 0; j < N; ++j) {
                double h = row[j] - ui - v[j];
                if (h < min2) {
                    if (h >= min1) { min2 = h; }
                    else { min2 = min1; min1 = h; j1 = j; }
                }
            }
            double delta = min2 - min1;
            if (delta > 0) v[j1] -= delta;
            u[i] = ui + min2;
            int r = y[j1];
            if (r >= 0) x[r] = -1;
            x[i] = j1; y[j1] = i;
        }
    }

    // ---------- augmentation (Dijkstra, no heap) ----------
    std::vector<double> dist(N);
    std::vector<int> pred(N);
    std::vector<char> scanned(N);

    for (int i0 = 0; i0 < N; ++i0) {
        if (x[i0] >= 0) continue;
        const double* row0 = cost + (size_t)i0 * N;
        double ui0 = u[i0];
        for (int j = 0; j < N; ++j) {
            dist[j] = row0[j] - ui0 - v[j];
            pred[j] = i0;
            scanned[j] = 0;
        }
        int j_end = -1;
        while (true) {
            double mn = INF; int jmin = -1;
            for (int j = 0; j < N; ++j) if (!scanned[j] && dist[j] < mn) { mn = dist[j]; jmin = j; }
            scanned[jmin] = 1;
            if (y[jmin] < 0) { j_end = jmin; break; }
            int r = y[jmin];
            const double* row = cost + (size_t)r * N;
            double base = mn - (row[jmin] - v[jmin]);
            for (int j2 = 0; j2 < N; ++j2) if (!scanned[j2]) {
                double nd = base + row[j2] - v[j2];
                if (nd < dist[j2]) { dist[j2] = nd; pred[j2] = r; }
            }
        }
        double D = dist[j_end];
        for (int j = 0; j < N; ++j) if (scanned[j]) v[j] -= (D - dist[j]);
        u[i0] += D;
        for (int j = 0; j < N; ++j) if (scanned[j] && y[j] >= 0) {
            int r = y[j];
            u[r] = cost[(size_t)r * N + j] - v[j];
        }
        // augment
        int j = j_end;
        while (true) {
            int r = pred[j];
            int jprev = x[r];
            x[r] = j; y[j] = r;
            if (r == i0) break;
            j = jprev;
        }
    }

    for (int i = 0; i < N; ++i) row_of_out[i] = x[i];
}
