// Exact assignment solver. Cost is stored transposed so the shortest-path
// relaxation scans contiguous memory.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>

static const double INF = 1e100;

extern "C" void solve_assignment(const double* cost, int n, int* row_of_out) {
    const int N = n;
    // transpose: T[j*N + i] = cost[i*N + j]
    std::vector<double> T((size_t)N * N);
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            T[(size_t)j * N + i] = cost[(size_t)i * N + j];

    std::vector<double> u(N, 0.0), v(N, 0.0);
    std::vector<int> x(N, -1), y(N, -1);

    // column reduction (columns are contiguous rows of T)
    for (int j = N - 1; j >= 0; --j) {
        const double* col = T.data() + (size_t)j * N;
        double mn = INF; int imin = 0;
        for (int i = 0; i < N; ++i) if (col[i] < mn) { mn = col[i]; imin = i; }
        v[j] = mn;
        if (x[imin] < 0) { x[imin] = j; y[j] = imin; }
    }

    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < N; ++i) {
            if (x[i] >= 0) continue;
            double min1 = INF, min2 = INF; int j1 = -1;
            double ui = u[i];
            for (int j = 0; j < N; ++j) {
                double h = T[(size_t)j * N + i] - ui - v[j];
                if (h < min2) {
                    if (h >= min1) min2 = h;
                    else { min2 = min1; min1 = h; j1 = j; }
                }
            }
            if (min2 > min1) v[j1] -= (min2 - min1);
            u[i] = ui + min2;
            int r = y[j1];
            if (r >= 0) x[r] = -1;
            x[i] = j1; y[j1] = i;
        }
    }

    std::vector<double> dist(N);
    std::vector<int> pred(N);
    std::vector<char> scanned(N);
    std::vector<int> unscanned(N);

    for (int i0 = 0; i0 < N; ++i0) {
        if (x[i0] >= 0) continue;
        double ui0 = u[i0];
        for (int j = 0; j < N; ++j) {
            dist[j] = T[(size_t)j * N + i0] - ui0 - v[j];
            pred[j] = i0;
        }
        int nscan = N;
        for (int j = 0; j < N; ++j) unscanned[j] = j;

        int j_end = -1;
        while (true) {
            double mn = INF; int pos = -1;
            for (int s = 0; s < nscan; ++s) {
                int j = unscanned[s];
                if (dist[j] < mn) { mn = dist[j]; pos = s; }
            }
            int jmin = unscanned[pos];
            unscanned[pos] = unscanned[--nscan];
            if (y[jmin] < 0) { j_end = jmin; break; }
            int r = y[jmin];
            double base = mn - (T[(size_t)jmin * N + r] - v[jmin]);
            // relax over remaining columns; each column's cost to row r is contiguous
            for (int s = 0; s < nscan; ++s) {
                int j2 = unscanned[s];
                double nd = base + T[(size_t)j2 * N + r] - v[j2];
                if (nd < dist[j2]) { dist[j2] = nd; pred[j2] = r; }
            }
        }
        double D = dist[j_end];
        for (int j = 0; j < N; ++j) if (dist[j] <= D) v[j] -= (D - dist[j]);
        u[i0] += D;
        for (int j = 0; j < N; ++j) if (dist[j] <= D && y[j] >= 0) {
            int r = y[j];
            u[r] = T[(size_t)j * N + r] - v[j];
        }
        int j = j_end;
        while (true) {
            int r = pred[j];
            int jprev = x[r];
            x[r] = j; y[j] = r;
            if (r == i0) break;
            j = jprev;
        }
    }
    for (int i = 0; i < N; ++i) row_of_out[i] = x[i];
}
