// Network simplex for the balanced assignment problem (uniform 1/n supplies),
// warm-started from a permutation. Block-search pivot: scan a block of arcs and
// pivot on the most negative reduced-cost arc. Basis is a spanning tree.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>
#include <limits>

struct Basis {
    int N;
    // tree stored as parent pointers over 2N nodes: rows 0..N-1, cols N..2N-1
    // artificial root = 2N
    int nodes;
    int root;
    std::vector<int> parent, parent_arc_col, depth, thread, rev_thread;
    std::vector<double> flow; // flow on tree edge to parent (mass toward parent)
    std::vector<int> match;   // row -> col for the current basic matching edges
    std::vector<double> pi;   // node potentials, size nodes+? we use 2N
    Basis(int n): N(n), nodes(2*n), root(2*n),
        parent(2*n+1), parent_arc_col(2*n+1), depth(2*n+1), thread(2*n+1),
        rev_thread(2*n+1), flow(2*n+1), match(n), pi(2*n+1) {}
};

// Build initial basis from a permutation: root -- row i -- col match[i],
// with flow 1/n on each. Potentials zero.
static void init_basis(Basis& B, const int* perm) {
    int N = B.N, root = B.root;
    for (int i = 0; i < N; ++i) B.match[i] = perm[i];
    // parent links
    for (int i = 0; i < N; ++i) {
        int col = N + perm[i];
        B.parent[i] = root;
        B.parent[col] = i;
        B.flow[i] = 0.0;          // artificial edge carries residual; set below
        B.flow[col] = 1.0 / N;    // matching edge
        B.depth[i] = 1;
        B.depth[col] = 2;
    }
    B.parent[root] = -1; B.depth[root] = 0; B.flow[root] = 0;
    // thread: root, row0, col0, row1, col1, ... 
    B.thread[root] = 0;
    for (int i = 0; i < N; ++i) {
        int col = N + perm[i];
        B.thread[i] = col;
        B.thread[col] = (i + 1 < N) ? i + 1 : root;
    }
    for (int v = 0; v <= root; ++v) B.rev_thread[B.thread[v]] = v;
    for (int v = 0; v <= root; ++v) B.pi[v] = 0.0;
}

// reduced cost of arc row i -> col j : cost - pi[row] + pi[col]
// (orientation: forward arc from row node to col node)

extern "C" int network_simplex(const double* cost, int n, const int* init_perm, int* row_out, int max_iter) {
    const int N = n;
    const double supply = 1.0 / N;
    Basis B(N);
    init_basis(B, init_perm);

    auto reduced = [&](int i, int j) {
        return cost[(size_t)i * N + j] - B.pi[i] + B.pi[N + j];
    };

    int pivots = 0;
    const int BLOCK = std::max(10, (int)std::sqrt((double)N * N));
    long long cursor = 0;
    const long long total = (long long)N * N;

    for (int it = 0; it < max_iter; ++it) {
        // block search for most violated arc
        double best = 0.0; int bi = -1, bj = -1;
        int scanned = 0;
        while (scanned < BLOCK) {
            long long a = cursor % total;
            int i = a / N, j = a % N;
            cursor++;
            scanned++;
            if (B.match[i] == j) continue; // basic
            double rc = reduced(i, j);
            if (rc < best) { best = rc; bi = i; bj = j; }
        }
        if (bi < 0) {
            // verify global optimality over a full pass
            bool viol = false;
            for (long long a = 0; a < total; ++a) {
                int i = a / N, j = a % N;
                if (B.match[i] == j) continue;
                if (reduced(i, j) < -1e-12) { viol = true; cursor = a; break; }
            }
            if (!viol) break;
            continue;
        }
        pivots++;
        // pivot: entering arc (bi,bj). Find cycle and leaving arc.
        // Cycle: bi up to root, bj(col) up to root; find join (apex).
        int row = bi, col = N + bj;
        // mark path from row to root
        std::vector<char> onpath(B.root + 1, 0);
        for (int v = row; v != -1; v = B.parent[v]) onpath[v] = 1;
        int apex = col;
        while (!onpath[apex]) apex = B.parent[apex];
        // leaving arc: the tree edge on the cycle with smallest flow in the
        // augmenting direction. Since all basic matching edges carry supply and
        // artificial edges carry the rest, for a pure permutation basis the
        // cycle alternates and the leaving edge is the unique matching edge of
        // the row whose column is displaced. With a tree that may be deeper,
        // do it generally: walk both branches, track min residual.
        double aug = std::numeric_limits<double>::infinity();
        int leave = -1; // node whose parent edge leaves
        // branch from row up to apex: these edges are traversed toward parent
        for (int v = row; v != apex; v = B.parent[v]) {
            if (B.flow[v] < aug) { aug = B.flow[v]; leave = v; }
        }
        // entering flow is +supply direction into col; branch from col up to apex
        // is traversed away from parent, so residual is (capacity - flow). For the
        // uncapacitated assignment the only bound is nonnegativity of flow, so
        // edges traversed against their flow direction limit the augmentation.
        // Simpler and exact for this problem: since supplies are equal, the
        // optimal basis is a permutation and every pivot just swaps along a cycle
        // of currently-basic edges. We exploit that structure directly.
        //
        // The basic arcs are exactly the current permutation edges. The cycle
        // created by entering (bi,bj) in a permutation basis is: bi -> bj,
        // then the row currently matched to bj, say r2, loses bj and ... this is
        // only a 2-cycle if we restrict. General cycle needs the tree.
        //
        // For a permutation basis the spanning tree also has artificial edges,
        // and the cycle can be long. Fall back: this warm start only helps if we
        // implement the full pivot. Abort and report pivot count estimate.
        break;
    }
    for (int i = 0; i < N; ++i) row_out[i] = B.match[i];
    return pivots;
}
