// Jonker-Volgenant LAPMOD-style dense assignment solver.
// Column reduction, reduction transfer, augmenting row reduction,
// then successive shortest augmenting paths with a Dial-like partial scan.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>
#include <limits>

static const double INF = 1e100;

extern "C" void solve_assignment(const double* cost, int n, int* row_out) {
    const int N = n;
    std::vector<double> v(N, 0.0), u(N, 0.0);
    std::vector<int> rowsol(N, -1), colsol(N, -1);

    // ---- COLUMN REDUCTION ----
    std::vector<int> minrow(N);
    for (int j = 0; j < N; ++j) {
        double mn = INF; int r = 0;
        const double* c = cost + j; // strided
        for (int i = 0; i < N; ++i) { double h = cost[(size_t)i*N + j]; if (h < mn) { mn = h; r = i; } }
        v[j] = mn; minrow[j] = r;
    }
    std::vector<char> taken(N, 0);
    for (int j = N - 1; j >= 0; --j) {
        int i = minrow[j];
        if (!taken[i]) { rowsol[i] = j; colsol[j] = i; taken[i] = 1; }
    }

    // ---- REDUCTION TRANSFER ----
    for (int i = 0; i < N; ++i) if (rowsol[i] < 0) {
        double mn = INF;
        const double* row = cost + (size_t)i*N;
        for (int j = 0; j < N; ++j) { double h = row[j] - v[j]; if (h < mn) mn = h; }
        u[i] = mn;
    }

    // ---- AUGMENTING ROW REDUCTION ----
    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < N; ++i) if (rowsol[i] < 0) {
            const double* row = cost + (size_t)i*N;
            double mn1 = INF, mn2 = INF; int j1 = -1;
            for (int j = 0; j < N; ++j) {
                double h = row[j] - v[j];
                if (h < mn2) {
                    if (h >= mn1) mn2 = h;
                    else { mn2 = mn1; mn1 = h; j1 = j; }
                }
            }
            v[j1] -= (mn2 - mn1);
            u[i] = mn2;
            int iold = colsol[j1];
            if (iold >= 0) rowsol[iold] = -1;
            rowsol[i] = j1; colsol[j1] = i;
        }
    }

    // ---- AUGMENTATION ----
    std::vector<double> dist(N);
    std::vector<int> pred(N);
    std::vector<int> active(N);
    std::vector<char> in_active(N);

    for (int i0 = 0; i0 < N; ++i0) {
        if (rowsol[i0] >= 0) continue;
        const double* row0 = cost + (size_t)i0*N;
        double ui0 = u[i0];
        int nact = 0;
        for (int j = 0; j < N; ++j) {
            dist[j] = row0[j] - v[j] - ui0;
            pred[j] = i0;
            active[nact++] = j;
            in_active[j] = 1;
        }
        int j_end = -1;
        double D = 0;
        while (true) {
            // find min among active
            double mn = INF; int pos = -1;
            for (int s = 0; s < nact; ++s) {
                double d = dist[active[s]];
                if (d < mn) { mn = d; pos = s; }
            }
            int jmin = active[pos];
            active[pos] = active[--nact];
            in_active[jmin] = 0;
            D = mn;
            if (colsol[jmin] < 0) { j_end = jmin; break; }
            int r = colsol[jmin];
            const double* row = cost + (size_t)r*N;
            double base = mn - (row[jmin] - v[jmin]);
            for (int s = 0; s < nact; ++s) {
                int j2 = active[s];
                double nd = base + row[j2] - v[j2];
                if (nd < dist[j2]) { dist[j2] = nd; pred[j2] = r; }
            }
        }
        // dual update
        for (int j = 0; j < N; ++j) if (!in_active[j]) v[j] -= (D - dist[j]);
        u[i0] += D;
        for (int j = 0; j < N; ++j) if (!in_active[j] && colsol[j] >= 0) {
            int r = colsol[j];
            u[r] = cost[(size_t)r*N + j] - v[j];
        }
        // augment
        int j = j_end;
        while (true) {
            int r = pred[j];
            colsol[j] = r;
            int jp = rowsol[r];
            rowsol[r] = j;
            if (r == i0) break;
            j = jp;
        }
    }
    for (int i = 0; i < N; ++i) row_out[i] = rowsol[i];
}
