// Exact assignment via successive shortest augmenting paths with a binary heap.
// Each augmentation only touches columns that are actually relaxed, so the cost
// tracks the (small) search-tree size rather than n per scan.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>
#include <limits>

struct Heap {
    std::vector<int> h, pos;
    std::vector<double> key;
    int n;
    explicit Heap(int N): h(N), pos(N, -1), key(N), n(0) {}
    void clear() { for (int i = 0; i < n; ++i) pos[h[i]] = -1; n = 0; }
    void up(int i) {
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (key[h[p]] <= key[h[i]]) break;
            std::swap(h[p], h[i]); pos[h[p]] = p; pos[h[i]] = i; i = p;
        }
    }
    void down(int i) {
        while (true) {
            int l = i*2+1, r = l+1, b = i;
            if (l < n && key[h[l]] < key[h[b]]) b = l;
            if (r < n && key[h[r]] < key[h[b]]) b = r;
            if (b == i) break;
            std::swap(h[i], h[b]); pos[h[i]] = i; pos[h[b]] = b; i = b;
        }
    }
    void push(int j, double k) { key[j] = k; pos[j] = n; h[n] = j; n++; up(n-1); }
    void decrease(int j, double k) {
        if (pos[j] < 0) { push(j, k); return; }
        if (k >= key[j]) return;
        key[j] = k; up(pos[j]);
    }
    int pop() {
        int r = h[0]; pos[r] = -2; // -2 = popped/settled
        n--;
        if (n) { h[0] = h[n]; pos[h[0]] = 0; down(0); }
        return r;
    }
    bool empty() const { return n == 0; }
    bool settled(int j) const { return pos[j] == -2; }
};

extern "C" void solve_assignment(const double* cost, int n, int* row_out) {
    const int N = n;
    const double INF = std::numeric_limits<double>::infinity();
    std::vector<double> u(N, 0.0), v(N, 0.0);
    std::vector<int> x(N, -1), y(N, -1);

    // column reduction
    for (int j = N - 1; j >= 0; --j) {
        double mn = INF; int imin = 0;
        for (int i = 0; i < N; ++i) {
            double h = cost[(size_t)i*N + j];
            if (h < mn) { mn = h; imin = i; }
        }
        v[j] = mn;
        if (x[imin] < 0) { x[imin] = j; y[j] = imin; }
    }
    // augmenting row reduction
    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < N; ++i) if (x[i] < 0) {
            const double* row = cost + (size_t)i*N;
            double mn1 = INF, mn2 = INF; int j1 = -1;
            double ui = u[i];
            for (int j = 0; j < N; ++j) {
                double h = row[j] - ui - v[j];
                if (h < mn2) {
                    if (h >= mn1) mn2 = h;
                    else { mn2 = mn1; mn1 = h; j1 = j; }
                }
            }
            if (mn2 > mn1) v[j1] -= (mn2 - mn1);
            u[i] = ui + mn2;
            int r = y[j1];
            if (r >= 0) x[r] = -1;
            x[i] = j1; y[j1] = i;
        }
    }

    std::vector<double> dist(N);
    std::vector<int> pred(N);
    std::vector<int> touched; touched.reserve(N);
    Heap heap(N);

    for (int i0 = 0; i0 < N; ++i0) {
        if (x[i0] >= 0) continue;
        heap.clear();
        touched.clear();
        const double* row0 = cost + (size_t)i0*N;
        double ui0 = u[i0];
        for (int j = 0; j < N; ++j) {
            dist[j] = row0[j] - ui0 - v[j];
            pred[j] = i0;
            heap.push(j, dist[j]);
        }
        int j_end = -1;
        while (!heap.empty()) {
            int jmin = heap.pop();
            touched.push_back(jmin);
            if (y[jmin] < 0) { j_end = jmin; break; }
            int r = y[jmin];
            const double* row = cost + (size_t)r*N;
            double base = dist[jmin] - (row[jmin] - v[jmin]);
            for (int j2 = 0; j2 < N; ++j2) {
                if (heap.settled(j2)) continue;
                double nd = base + row[j2] - v[j2];
                if (nd < dist[j2]) { dist[j2] = nd; pred[j2] = r; heap.decrease(j2, nd); }
            }
        }
        double D = dist[j_end];
        for (int j : touched) v[j] -= (D - dist[j]);
        u[i0] += D;
        for (int j : touched) if (y[j] >= 0) {
            int r = y[j];
            u[r] = cost[(size_t)r*N + j] - v[j];
        }
        int j = j_end;
        while (true) {
            int r = pred[j];
            int jp = x[r];
            x[r] = j; y[j] = r;
            if (r == i0) break;
            j = jp;
        }
    }
    for (int i = 0; i < N; ++i) row_out[i] = x[i];
}
