// Exact assignment by successive shortest augmenting paths.
// Relaxation uses a sparse neighbor list: for each row only columns whose cost
// is below a threshold can ever enter an optimal basis, so the dense scan is
// replaced by a short list. Correctness is guaranteed by keeping the threshold
// above the optimum and by a dense fallback when a distance bound exceeds it.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstring>
#include <limits>

struct Heap {
    std::vector<int> h, pos;
    std::vector<double> key;
    int n;
    explicit Heap(int N): h(N), pos(N, -1), key(N), n(0) {}
    void clear() { for (int i = 0; i < n; ++i) pos[h[i]] = -1; n = 0; }
    void up(int i) {
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (key[h[p]] <= key[h[i]]) break;
            std::swap(h[p], h[i]); pos[h[p]] = p; pos[h[i]] = i; i = p;
        }
    }
    void down(int i) {
        while (true) {
            int l = i*2+1, r = l+1, b = i;
            if (l < n && key[h[l]] < key[h[b]]) b = l;
            if (r < n && key[h[r]] < key[h[b]]) b = r;
            if (b == i) break;
            std::swap(h[i], h[b]); pos[h[i]] = i; pos[h[b]] = b; i = b;
        }
    }
    void push(int j, double k) { key[j] = k; pos[j] = n; h[n] = j; n++; up(n-1); }
    void decrease(int j, double k) {
        if (pos[j] < 0) { push(j, k); return; }
        if (k >= key[j]) return;
        key[j] = k; up(pos[j]);
    }
    int pop() {
        int r = h[0]; pos[r] = -2;
        n--;
        if (n) { h[0] = h[n]; pos[h[0]] = 0; down(0); }
        return r;
    }
    bool empty() const { return n == 0; }
    bool settled(int j) const { return pos[j] == -2; }
};

extern "C" void solve_assignment(const double* cost, int n, int* row_out) {
    const int N = n;
    const double INF = std::numeric_limits<double>::infinity();

    // sparse neighbor lists: per row, columns with cost below threshold
    double thr = 0.35;
    std::vector<std::vector<int>> nbr(N);
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i*N;
        nbr[i].reserve(64);
        for (int j = 0; j < N; ++j) if (row[j] < thr) nbr[i].push_back(j);
    }

    std::vector<double> u(N, 0.0), v(N, 0.0);
    std::vector<int> x(N, -1), y(N, -1);

    for (int j = N - 1; j >= 0; --j) {
        double mn = INF; int imin = 0;
        for (int i = 0; i < N; ++i) {
            double h = cost[(size_t)i*N + j];
            if (h < mn) { mn = h; imin = i; }
        }
        v[j] = mn;
        if (x[imin] < 0) { x[imin] = j; y[j] = imin; }
    }
    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < N; ++i) if (x[i] < 0) {
            const double* row = cost + (size_t)i*N;
            double mn1 = INF, mn2 = INF; int j1 = -1;
            double ui = u[i];
            for (int j = 0; j < N; ++j) {
                double h = row[j] - ui - v[j];
                if (h < mn2) {
                    if (h >= mn1) mn2 = h;
                    else { mn2 = mn1; mn1 = h; j1 = j; }
                }
            }
            if (mn2 > mn1) v[j1] -= (mn2 - mn1);
            u[i] = ui + mn2;
            int r = y[j1];
            if (r >= 0) x[r] = -1;
            x[i] = j1; y[j1] = i;
        }
    }

    std::vector<double> dist(N, INF);
    std::vector<int> pred(N, -1);
    std::vector<int> touched;
    std::vector<char> seen(N, 0);
    Heap heap(N);

    auto reset = [&]() {
        for (int j : touched) { dist[j] = INF; pred[j] = -1; seen[j] = 0; }
        touched.clear();
        heap.clear();
    };
    auto visit = [&](int j, double d, int p) {
        if (!seen[j]) { seen[j] = 1; touched.push_back(j); dist[j] = INF; }
        if (d < dist[j]) { dist[j] = d; pred[j] = p; heap.decrease(j, d); }
    };

    for (int i0 = 0; i0 < N; ++i0) {
        if (x[i0] >= 0) continue;
        reset();
        const double* row0 = cost + (size_t)i0*N;
        double ui0 = u[i0];
        // seed only neighbor columns; others start at their true distance lazily
        for (int j : nbr[i0]) visit(j, row0[j] - ui0 - v[j], i0);
        // also seed the free columns' distances if not covered? handled by bound

        // upper bound: best free column reachable. Compute exact min over free cols once.
        double Dub = INF;
        for (int j = 0; j < N; ++j) if (y[j] < 0) {
            double d = row0[j] - ui0 - v[j];
            if (d < Dub) Dub = d;
            visit(j, d, i0);
        }

        int j_end = -1;
        bool sparse_ok = true;
        while (!heap.empty()) {
            int jmin = heap.pop();
            if (dist[jmin] >= Dub - 1e-15) { j_end = -2; break; }
            if (y[jmin] < 0) { j_end = jmin; Dub = dist[jmin]; break; }
            int r = y[jmin];
            const double* row = cost + (size_t)r*N;
            double base = dist[jmin] - (row[jmin] - v[jmin]);
            // a column j can improve only if cost[r,j] < Dub - base + v[j]
            double limit = Dub - base; // since v[j] <= 0 typically; use conservative: cost < Dub-base - min_v
            if (limit > thr) { sparse_ok = false; break; }
            for (int j2 : nbr[r]) {
                if (heap.settled(j2)) continue;
                double nd = base + row[j2] - v[j2];
                if (nd < Dub && nd < dist[j2]) visit(j2, nd, r);
            }
            // update bound from free columns in neighbor list
            for (int j2 : nbr[r]) if (y[j2] < 0 && dist[j2] < Dub) Dub = dist[j2];
        }
        if (!sparse_ok || j_end == -1) {
            // dense fallback for this augmentation
            reset();
            for (int j = 0; j < N; ++j) visit(j, row0[j] - ui0 - v[j], i0);
            Dub = INF;
            for (int j = 0; j < N; ++j) if (y[j] < 0 && dist[j] < Dub) Dub = dist[j];
            j_end = -1;
            while (!heap.empty()) {
                int jmin = heap.pop();
                if (y[jmin] < 0) { j_end = jmin; break; }
                int r = y[jmin];
                const double* row = cost + (size_t)r*N;
                double base = dist[jmin] - (row[jmin] - v[jmin]);
                for (int j2 = 0; j2 < N; ++j2) {
                    if (heap.settled(j2)) continue;
                    double nd = base + row[j2] - v[j2];
                    if (nd < dist[j2]) { dist[j2] = nd; pred[j2] = r; heap.decrease(j2, nd); }
                }
            }
        }
        double D = dist[j_end];
        for (int j : touched) if (heap.settled(j)) v[j] -= (D - dist[j]);
        u[i0] += D;
        for (int j : touched) if (heap.settled(j) && y[j] >= 0) {
            int r = y[j];
            u[r] = cost[(size_t)r*N + j] - v[j];
        }
        int j = j_end;
        while (true) {
            int r = pred[j];
            int jp = x[r];
            x[r] = j; y[j] = r;
            if (r == i0) break;
            j = jp;
        }
    }
    for (int i = 0; i < N; ++i) row_out[i] = x[i];
}
