// Epsilon-scaling auction on a sparse k-nearest-neighbor graph, with a dense
// refinement phase at the end to guarantee the exact optimum.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>
#include <cstring>

struct Row {
    std::vector<int> idx;
    std::vector<double> val;
};

static void ksmallest(const double* row, int N, int k, int* out_idx, double* out_val) {
    // partial selection of k smallest via nth_element on index array
    std::vector<int> id(N);
    for (int j = 0; j < N; ++j) id[j] = j;
    std::nth_element(id.begin(), id.begin() + k, id.end(),
                     [&](int a, int b){ return row[a] < row[b]; });
    for (int t = 0; t < k; ++t) { out_idx[t] = id[t]; out_val[t] = row[id[t]]; }
}

extern "C" int auction(const double* cost, int n, int* rowsol) {
    const int N = n;
    const int K = 48;

    std::vector<int> idx((size_t)N * K);
    std::vector<double> val((size_t)N * K);
    for (int i = 0; i < N; ++i)
        ksmallest(cost + (size_t)i*N, N, K, idx.data() + (size_t)i*K, val.data() + (size_t)i*K);

    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), assign(N, -1);
    std::vector<int> un(N), next(N);

    auto run_phase = [&](double eps, bool sparse, long guardmax) -> bool {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        for (int i = 0; i < N; ++i) un[i] = i;
        int nun = N;
        long guard = 0;
        while (nun > 0 && guard++ < guardmax) {
            int newn = 0;
            for (int u = 0; u < nun; ++u) {
                int i = un[u];
                double best = std::numeric_limits<double>::infinity();
                double second = std::numeric_limits<double>::infinity();
                int bj = 0;
                if (sparse) {
                    const int* id = idx.data() + (size_t)i*K;
                    const double* vv = val.data() + (size_t)i*K;
                    for (int t = 0; t < K; ++t) {
                        double w = vv[t] + price[id[t]];
                        if (w < best) { second = best; best = w; bj = id[t]; }
                        else if (w < second) second = w;
                    }
                } else {
                    const double* row = cost + (size_t)i*N;
                    for (int j = 0; j < N; ++j) {
                        double w = row[j] + price[j];
                        if (w < best) { second = best; best = w; bj = j; }
                        else if (w < second) second = w;
                    }
                }
                double bid = price[bj] + (second - best) + eps;
                int prev = owner[bj];
                if (prev != -1) { assign[prev] = -1; next[newn++] = prev; }
                owner[bj] = i;
                assign[i] = bj;
                price[bj] = bid;
            }
            un.swap(next);
            nun = newn;
        }
        return nun == 0;
    };

    double range = 1.0;
    double eps = range / 4.0;
    // sparse scaling down to a moderate epsilon
    for (int phase = 0; phase < 12; ++phase) {
        bool ok = run_phase(eps, true, (long)N * 400);
        if (!ok) std::fill(price.begin(), price.end(), 0.0);
        eps *= 0.25;
    }
    // dense refinement at fine epsilon, continuing from current prices
    double eps_min = range / (N + 1.0) / (N + 1.0) / 50.0;
    bool done = false;
    for (int phase = 0; phase < 20 && eps > eps_min * 0.2; ++phase) {
        if (eps < eps_min) eps = eps_min;
        done = run_phase(eps, false, (long)N * 2000);
        if (!done) std::fill(price.begin(), price.end(), 0.0);
        if (eps <= eps_min && done) break;
        eps *= 0.2;
    }

    int ok = 1;
    std::vector<char> seen(N, 0);
    for (int i = 0; i < N; ++i) {
        int j = assign[i];
        rowsol[i] = j;
        if (j < 0 || j >= N || seen[j]) ok = 0; else seen[j] = 1;
    }
    return ok;
}
