// Epsilon-scaling auction. Each bid is evaluated on a k-nearest shortlist and
// only falls back to a full row scan when the shortlist cannot certify the two
// best objects. This is exact: the fallback triggers whenever a non-shortlisted
// column could be among the two cheapest.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>
#include <cstring>

extern "C" int auction(const double* cost, int n, int* rowsol) {
    const int N = n;
    const int K = 24;

    std::vector<int> nb((size_t)N * K);
    std::vector<double> nbv((size_t)N * K);
    std::vector<double> kth(N);
    std::vector<int> id(N);
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i*N;
        for (int j = 0; j < N; ++j) id[j] = j;
        std::nth_element(id.begin(), id.begin() + K, id.end(),
                         [&](int a, int b){ return row[a] < row[b]; });
        double mx = -std::numeric_limits<double>::infinity();
        for (int t = 0; t < K; ++t) {
            nb[(size_t)i*K + t] = id[t];
            nbv[(size_t)i*K + t] = row[id[t]];
            mx = std::max(mx, row[id[t]]);
        }
        kth[i] = mx;
    }

    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), assign(N, -1);
    std::vector<int> un(N), next(N);

    double range = 1.0;
    double eps = range / 4.0;
    double eps_min = range / (N + 1.0) / (N + 1.0) / 50.0;

    long long sparse_bids = 0, dense_bids = 0;

    for (int phase = 0; phase < 60; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        for (int i = 0; i < N; ++i) un[i] = i;
        int nun = N;
        long guard = 0;
        long guardmax = (long)N * 2000;
        while (nun > 0 && guard++ < guardmax) {
            int newn = 0;
            for (int u = 0; u < nun; ++u) {
                int i = un[u];
                const int* idp = nb.data() + (size_t)i*K;
                const double* vp = nbv.data() + (size_t)i*K;
                double best = std::numeric_limits<double>::infinity();
                double second = std::numeric_limits<double>::infinity();
                int bj = 0;
                double pmax = -std::numeric_limits<double>::infinity();
                for (int t = 0; t < K; ++t) {
                    double pj = price[idp[t]];
                    if (pj > pmax) pmax = pj;
                    double w = vp[t] + pj;
                    if (w < best) { second = best; best = w; bj = idp[t]; }
                    else if (w < second) second = w;
                }
                // a column outside the shortlist costs at least kth[i] and has
                // price at least the global minimum; use the min price outside
                // the shortlist. Conservative bound: min price overall.
                double pmin = std::numeric_limits<double>::infinity();
                for (int j = 0; j < N; ++j) if (price[j] < pmin) pmin = price[j];
                bool cert = (kth[i] + pmin) >= second - 1e-15;
                if (!cert) {
                    dense_bids++;
                    const double* row = cost + (size_t)i*N;
                    best = std::numeric_limits<double>::infinity();
                    second = std::numeric_limits<double>::infinity();
                    for (int j = 0; j < N; ++j) {
                        double w = row[j] + price[j];
                        if (w < best) { second = best; best = w; bj = j; }
                        else if (w < second) second = w;
                    }
                } else sparse_bids++;
                double bid = price[bj] + (second - best) + eps;
                int prev = owner[bj];
                if (prev != -1) { assign[prev] = -1; next[newn++] = prev; }
                owner[bj] = i;
                assign[i] = bj;
                price[bj] = bid;
            }
            un.swap(next);
            nun = newn;
        }
        bool done = (nun == 0);
        if (!done) std::fill(price.begin(), price.end(), 0.0);
        if (eps <= eps_min && done) break;
        eps *= 0.2;
        if (eps < eps_min) eps = eps_min;
    }

    int ok = 1;
    std::vector<char> seen(N, 0);
    for (int i = 0; i < N; ++i) {
        int j = assign[i];
        rowsol[i] = j;
        if (j < 0 || j >= N || seen[j]) ok = 0; else seen[j] = 1;
    }
    // stash counts in rowsol tail? report via stderr
    fprintf(stderr, "sparse %lld dense %lld\n", sparse_bids, dense_bids);
    return ok;
}
