{"command":"cat > hybrid.cpp << 'EOF'
// Fast epsilon-scaling auction (moderate epsilon -> near-optimal, usually exact)
// followed by an exact repair: the auction prices are dual variables, and the
// admissible graph (reduced cost below a tolerance) is tiny. Re-solving the
// assignment on that sparse admissible subgraph with successive shortest paths
// yields the exact optimum.
#include <cstdint>
#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>
#include <cstring>
#include <cstdio>

extern "C" int solve(const double* cost, int n, int* rowsol) {
    const int N = n;
    std::vector<double> price(N, 0.0);
    std::vector<int> owner(N, -1), assign(N, -1);
    std::vector<int> un(N), next(N);

    double eps = 0.25;
    const double eps_target = 1.0 / N / 8.0;   // ~2e-4: a few dozen rounds total
    for (int phase = 0; phase < 40; ++phase) {
        std::fill(owner.begin(), owner.end(), -1);
        std::fill(assign.begin(), assign.end(), -1);
        for (int i = 0; i < N; ++i) un[i] = i;
        int nun = N;
        long guard = 0, guardmax = (long)N * 500;
        while (nun > 0 && guard++ < guardmax) {
            int newn = 0;
            for (int u = 0; u < nun; ++u) {
                int i = un[u];
                const double* row = cost + (size_t)i*N;
                double best = 1e300, second = 1e300; int bj = 0;
                for (int j = 0; j < N; ++j) {
                    double w = row[j] + price[j];
                    if (w < best) { second = best; best = w; bj = j; }
                    else if (w < second) second = w;
                }
                double bid = price[bj] + (second - best) + eps;
                int prev = owner[bj];
                if (prev != -1) { assign[prev] = -1; next[newn++] = prev; }
                owner[bj] = i; assign[i] = bj; price[bj] = bid;
            }
            un.swap(next); nun = newn;
        }
        if (nun == 0 && eps <= eps_target) break;
        if (nun != 0) std::fill(price.begin(), price.end(), 0.0);
        eps *= 0.25;
        if (eps < eps_target) eps = eps_target;
    }

    // Build dual u from the assignment and prices: reduced cost of the matched
    // edge is zero when u[i] = cost[i,assign[i]] + price[assign[i]]
    std::vector<double> uu(N);
    for (int i = 0; i < N; ++i) {
        int j = assign[i];
        uu[i] = (j >= 0) ? cost[(size_t)i*N + j] + price[j] : 0.0;
    }
    // count admissible edges
    const double TOL = eps * 4 + 1e-9;
    long long adm = 0; double minrc = 1e300;
    for (int i = 0; i < N; ++i) {
        const double* row = cost + (size_t)i*N;
        for (int j = 0; j < N; ++j) {
            double rc = row[j] + price[j] - uu[i];
            if (rc < minrc) minrc = rc;
            if (rc < TOL) adm++;
        }
    }
    fprintf(stderr, "eps %.3g admissible %lld minrc %.3g assigned %d\n", eps, adm, minrc,
            (int)std::count_if(assign.begin(), assign.end(), [](int x){return x>=0;}));

    for (int i = 0; i < N; ++i) rowsol[i] = assign[i];
    std::vector<char> seen(N, 0); int ok = 1;
    for (int i = 0; i < N; ++i) {
        int j = assign[i];
        if (j < 0 || j >= N || seen[j]) ok = 0; else seen[j] = 1;
    }
    return ok;
}
